    56|function getHighlightedSegments(text: string, query: string): HighlightSegment[] {
    57|  const normalizedQuery = query.trim();
    58|  if (!normalizedQuery) {
    59|    return [{ text, matched: false }];
    60|  }
    61|
    62|  const segments: HighlightSegment[] = [];
    63|  const matcher = new RegExp(`(${escapeRegExp(normalizedQuery)})`, 'ig');
    64|  let lastIndex = 0;
    65|  let match: RegExpExecArray | null;
    66|
    67|  while ((match = matcher.exec(text)) !== null) {
    68|    if (match.index > lastIndex) {
    69|      segments.push({ text: text.slice(lastIndex, match.index), matched: false });
    70|    }
    71|
    72|    segments.push({ text: match[0] ?? '', matched: true });
    73|    lastIndex = match.index + (match[0]?.length ?? 0);
    74|  }
    75|
    76|  if (lastIndex < text.length) {
    77|    segments.push({ text: text.slice(lastIndex), matched: false });
    78|  }
    79|
